program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    perimeter = []
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if grid[r][c] != 0:
                    perimeter.append(grid[r][c])
    frame = max(set(perimeter), key=perimeter.count)
    inner_counts = {}
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            v = grid[r][c]
            if v != 0 and v != frame:
                inner_counts[v] = inner_counts.get(v, 0) + 1
    fill = max(inner_counts, key=inner_counts.get)
    thickness = 0
    while r0 + thickness <= r1 - thickness and c0 + thickness <= c1 - thickness:
        border_cells = []
        rr_top, rr_bottom = r0 + thickness, r1 - thickness
        cc_left, cc_right = c0 + thickness, c1 - thickness
        for c in range(cc_left, cc_right + 1):
            border_cells.extend((grid[rr_top][c], grid[rr_bottom][c]))
        for r in range(rr_top + 1, rr_bottom):
            border_cells.extend((grid[r][cc_left], grid[r][cc_right]))
        if border_cells and all(v == frame for v in border_cells):
            thickness += 1
        else:
            break
    out = [row[:] for row in grid]
    for r in range(max(0, r0 - thickness), min(h, r1 + thickness + 1)):
        for c in range(max(0, c0 - thickness), min(w, c1 + thickness + 1)):
            if grid[r][c] == 0:
                out[r][c] = fill
    return out
'''
